head.script:
scwin.screenId = "jldfil52000";

///////// 1. 변수 및 선언 영역 /////////

scwin.form = null;


///////// 2. 초기화 영역 /////////

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = function () {
    let __rowCopies = [{ childId: "__rb0", fn: function () { return "전체 " + String($c.data.readValue("dma_pageContext", "totalCountIntValue", { silent: true })) + "건 [" + String($c.data.readValue("dma_pageContext", "currentPage", { silent: true })) + "/" + String($c.data.readValue("dma_pageContext", "totalPageCount", { silent: true })) + "Page]"; } }];
    $c.data.copyRows(__rowCopies);
};

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = function () {
    try {
        scwin.form = (document.prtDepoListForm || { elements: [] });

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil52000.onpageload' }); }
};

// 화면 전환 파라미터 수신 — 공용 $c.data.recvParamData (§106, 이름 고정 "paramData"; 실패 표출은 gcc 함수 몫). onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { $c.data.recvParamData('dma_pageContext'); };

// as-is 흐름 보존 — 스켈레톤이 대체한 함수가 쓰던 전역 선언
scwin.searchType = undefined; scwin.form = undefined;

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil52000.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.grd_prtDepoList_oncellclick
 * @author Inswave
 * @date 2026. 09. 06
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.grd_prtDepoList_oncellclick = async function (rowIndex, columnIndex, columnId) { try { let dl = $c.util.getComponent('dlt_prtDepoList'); let r = dl && dl.getRowJSON ? dl.getRowJSON(rowIndex) : null; if (!r) { return; } if (columnId === "__rowAct") { if (r["lstApprovYn"] === '0' && r["listProcsStatCd"] === '') { await scwin.sendPrtDepoWithd(r["prtdepoNo"], "2"); return; } if ((r["lstApprovYn"] === '0' || r["lstApprovYn"] === '3') && r["listProcsStatCd"] === '35') { await scwin.sendPrtDepoWithd(r["prtdepoNo"], "3"); return; } if ((r["lstApprovYn"] === '0' || r["lstApprovYn"] === '7') &&  r["listProcsStatCd"] === '37') { await scwin.sendPrtDepoWithd(r["prtdepoNo"], "3"); return; } if (r["lstApprovYn"] === '7' &&  r["listProcsStatCd"] === '38') { await scwin.sendPrtDepoWithd(r["prtdepoNo"], "3"); return; } if (r["lstApprovYn"] === '3' && (r["listProcsStatCd"] === '33' || r["listProcsStatCd"] === '36' || r["listProcsStatCd"] === '37')) { scwin.openAdjReqPop(r["prtdepoNo"], "150"); return; } return; } if (r["lstApprovYn"] === '0' && (r["listProcsStatCd"] === '' || r["listProcsStatCd"] === '35')) { await scwin.viewDetail(r["prtdepoNo"], r["lstApprovYn"], r["listProcsStatCd"]); return; } if (r["lstApprovYn"] === '3' && r["listProcsStatCd"] === '35') { await scwin.viewDetail(r["prtdepoNo"], r["lstApprovYn"], r["listProcsStatCd"]); return; } if ((r["lstApprovYn"] === '0' || r["lstApprovYn"] === '7') &&  r["listProcsStatCd"] === '37') { await scwin.viewDetail(r["prtdepoNo"], r["lstApprovYn"], r["listProcsStatCd"]); return; } if (r["lstApprovYn"] === '7' &&  r["listProcsStatCd"] === '38') { await scwin.viewDetail(r["prtdepoNo"], r["lstApprovYn"], r["listProcsStatCd"]); return; } await scwin.viewDetail(r["prtdepoNo"], r["lstApprovYn"], r["listProcsStatCd"]); return; } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: 'grd_prtDepoList.oncellclick' }); } };

/**
 * @event
 * @name scwin.btn_newWrite_onclick
 * @author Inswave
 * @date 2026. 09. 06
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_newWrite_onclick = function(e){
    try { let ev = e; let event = ev; let __self = (ev && (ev.element || ev.target || ev.srcElement)) || this; scwin.newWrite() 
    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil52000.btn_newWrite_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_viewDetail
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_viewDetail = async function () {
    const sbmOptions = {
        id: "tx_viewDetail",
        method: "post",
        action: "/listInvstg/prtDepo.do?method=loadDetail&bzCd=6",
        ref: "dma_viewDetailReq",
        target: "dlt_prtDepoList=body",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { notify: 'none', context: "jldfil52000.tx_viewDetail" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        if (res && res.responseJSON && res.responseJSON.message) { await $c.win.alert(res.responseJSON.message); }
        return res;
    }
    return res;
};

/**
 * @method
 * @name scwin.tx_searchCorpListByBeginIndex
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_searchCorpListByBeginIndex = async function () {
    const sbmOptions = {
        id: "tx_searchCorpListByBeginIndex",
        method: "post",
        action: "/listInvstg/prtDepoList.do?method=getPrtDepoList",
        ref: "dma_searchCorpListByBeginIndexReq",
        target: "dlt_prtDepoList=body",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { notify: 'none', context: "jldfil52000.tx_searchCorpListByBeginIndex" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        if (res && res.responseJSON && res.responseJSON.message) { await $c.win.alert(res.responseJSON.message); }
        return res;
    }
    return res;
};

/**
 * @method
 * @name scwin.tx_fn_delete
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_delete = async function () {
    const sbmOptions = {
        id: "tx_fn_delete",
        method: "post",
        action: "/listInvstg/prtDepoList.do",
        ref: "dma_deleteReq",
        target: "dlt_prtDepoList=body",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { notify: 'none', context: "jldfil52000.tx_fn_delete" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        if (res && res.responseJSON && res.responseJSON.message) { await $c.win.alert(res.responseJSON.message); }
        return res;
    }
    return res;
};

/**
 * @method
 * @name scwin.tx_sendPrtDepoWithd
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_sendPrtDepoWithd = async function () {
    const sbmOptions = {
        id: "tx_sendPrtDepoWithd",
        method: "post",
        action: "/listInvstg/prtDepoList.do",
        ref: "dma_sendPrtDepoWithdReq",
        target: "dlt_prtDepoList=body",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { notify: 'none', context: "jldfil52000.tx_sendPrtDepoWithd" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        if (res && res.responseJSON && res.responseJSON.message) { await $c.win.alert(res.responseJSON.message); }
        return res;
    }
    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @event
 * @name scwin.grd_prtDepoList_fillAct
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.grd_prtDepoList_fillAct = async function () { try { let dl = $c.util.getComponent('dlt_prtDepoList'); if (!dl || !dl.getTotalRow) { return; } for (let i = 0; i < dl.getTotalRow(); i++) { let r = dl.getRowJSON(i); let v = '-'; if (r) { if (r["lstApprovYn"] === '0' && r["listProcsStatCd"] === '') { v = "제출"; } else if ((r["lstApprovYn"] === '0' || r["lstApprovYn"] === '3') && r["listProcsStatCd"] === '35') { v = "제출"; } else if ((r["lstApprovYn"] === '0' || r["lstApprovYn"] === '7') &&  r["listProcsStatCd"] === '37') { v = "제출"; } else if (r["lstApprovYn"] === '7' &&  r["listProcsStatCd"] === '38') { v = "제출"; } else if (r["lstApprovYn"] === '3' && (r["listProcsStatCd"] === '33' || r["listProcsStatCd"] === '36' || r["listProcsStatCd"] === '37')) { v = "수정요청"; } } dl.setCellData(i, "__rowAct", v); } } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: 'grd_prtDepoList.fillAct' }); } };

/**
 * @method
 * @name scwin.viewDetail
 * @author Inswave
 * @date 2026. 09. 06
 * @param prtDepoNo approvYn procsStatCd
 * @returns
 * @hidden N
*/
scwin.viewDetail = async function (prtDepoNo, approvYn, procsStatCd) {
    $c.util.getComponent('dma_viewDetailReq').set('prtDepoNo', prtDepoNo);
    if (approvYn === '0' || approvYn === '7') {
        if (procsStatCd === '38') {
            scwin.searchType = '5';
        } else {
            scwin.searchType = '2';
        }
    } else {
        if (approvYn === '2') {
            if (procsStatCd === '38') {
                scwin.searchType = '5';
            } else {
                scwin.searchType = '1';
            }
        } else {
            if (approvYn === '3') {
                if (procsStatCd === '34') {
                    scwin.searchType = '1';
                } else {
                    if (procsStatCd === '35') {
                        scwin.searchType = '3';
                    } else {
                        scwin.searchType = '1';
                    }
                }
            } else {
                if (approvYn === '8') {
                    scwin.searchType = '4';
                } else {
                    if (approvYn === '9') {
                        scwin.searchType = '5';
                    }
                }
            }
        }
    }
    $c.util.getComponent('dma_viewDetailReq').set('searchType', scwin.searchType);
    scwin.form.action = '/listInvstg/prtDepo.do?method=loadDetail&bzCd=6';
    $c.util.getComponent('dma_viewDetailReq').set('method', 'loadDetail');
    await scwin.tx_viewDetail();
};


/**
 * @method
 * @name scwin.newWrite
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.newWrite = function () {
    $c.win.setPageFrameSrc($c.win.getFrame(), '/jldfil52100/jldfil52100.xml');
};


/**
 * @method
 * @name scwin.fn_New_Display
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.fn_New_Display = function () {
    ($c.util.getComponent('select_new_write') && $c.util.getComponent('select_new_write').show ? $c.util.getComponent('select_new_write').show() : console.warn('[sdd] show 대상 미해결: ' + 'select_new_write'));
};


/**
 * @method
 * @name scwin.fncSearch
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.fncSearch = async function () {
    let pageIndex = $c.util.getComponent('dma_viewDetailReq').get('pageIndex');
    $c.util.getComponent('dma_viewDetailReq').set('pageIndex', pageIndex);
    await scwin.searchCorpListByBeginIndex();
};


/**
 * @method
 * @name scwin.searchCorpListByBeginIndex
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.searchCorpListByBeginIndex = async function () {
    (document.prtDepoListForm || { elements: [] }).action = "/listInvstg/prtDepoList.do?method=getPrtDepoList";
    await scwin.tx_searchCorpListByBeginIndex();
};


/**
 * @method
 * @name scwin.fn_delete
 * @author Inswave
 * @date 2026. 09. 06
 * @param prtDepoNo
 * @returns
 * @hidden N
*/
scwin.fn_delete = async function (prtDepoNo) {
    $c.util.getComponent('dma_viewDetailReq').set('prtDepoNo', prtDepoNo);
    let rse = await $c.win.confirm("삭제 하시겠습니까? ");
    if (rse) {
        scwin.form.action = '/listInvstg/prtDepoList.do';
        $c.util.getComponent('dma_viewDetailReq').set('method', 'delPrtDepoWithd');
        await scwin.tx_fn_delete();
    }
};


/**
 * @method
 * @name scwin.sendPrtDepoWithd
 * @author Inswave
 * @date 2026. 09. 06
 * @param prtDepoNo updateType
 * @returns
 * @hidden N
*/
scwin.sendPrtDepoWithd = async function (prtDepoNo, updateType) {
    scwin.form = (document.prtDepoListForm || { elements: [] });
    let rse = await $c.win.confirm("제출 하시겠습니까? ");
    if (rse) {
        $c.util.getComponent('dma_viewDetailReq').set('prtDepoNo', prtDepoNo);
        $c.util.getComponent('dma_viewDetailReq').set('searchType', updateType);
        scwin.form.action = '/listInvstg/prtDepoList.do';
        $c.util.getComponent('dma_viewDetailReq').set('method', 'sendPrtDepoWithd');
        await scwin.tx_sendPrtDepoWithd();
    }
};



/**
 * @method
 * @name scwin.openAdjReqPop
 * @author Inswave
 * @date 2026. 09. 06
 * @param prtdepoNo listInvstgBzTpCd
 * @returns
 * @hidden N
*/
scwin.openAdjReqPop = async function (prtdepoNo, listInvstgBzTpCd) {
    const data = { bzProcsNo: prtdepoNo, listInvstgBzTpCd: listInvstgBzTpCd, listBzDtlTpCd: "23", callbackFn: "scwin.popupCallback" };
    const options = { id: "jldfil59411", popupName: "상장공시제출시스템 수정요청", width: 900, height: 380, frameModal: "top" };
    await $c.win.openPopup("/jldfil59411/jldfil59411.xml", options, data);
};

/**
 * @event
 * @name scwin.krxpage_pagenavigator_78_onclick
 * @author Inswave
 * @date 2026. 09. 06
 * @param index
 * @returns
 * @hidden N
*/
scwin.krxpage_pagenavigator_78_onclick = function (index) { try { $c.util.getComponent('dma_viewDetailReq').set('pageIndex', index); } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'krxpage_pagenavigator_78.page' }); } scwin.fncSearch(); };
